import { z } from 'zod';

// ---------------------------------------------------------------------------
// Identifiers and timestamps
// ---------------------------------------------------------------------------

/** Ids of rows we own (project, task, activity): uuidv7 generated by Postgres 18. */
export const RowId = z.uuid();

/** Ids of Better Auth rows (user, organization, apikey, invitation). @zamu/db stores them as uuid. */
export const AuthId = z.uuid();

export const UserId = AuthId;
export const WorkspaceId = AuthId;
export const ProjectId = RowId;
export const TaskId = RowId;
export const MilestoneId = RowId;
export const CycleId = RowId;
export const CommentId = RowId;
/** M5. */
export const LabelId = RowId;
/** M8. */
export const WaveId = RowId;

/**
 * Timestamps travel as ISO 8601 UTC strings. Servers may hand in a Date (what Drizzle returns);
 * parsing normalises both forms to `2026-10-22T18:19:06.997Z`.
 */
export const Timestamp = z
  .union([z.date(), z.iso.datetime({ offset: true })])
  .transform((value) => (value instanceof Date ? value : new Date(value)).toISOString())
  .pipe(z.iso.datetime());

/**
 * A calendar day without time or zone, `2026-11-14`. Milestone targets and cycle dates use it;
 * "today" is the day in the instance's APP_TIME_ZONE.
 */
export const CalendarDate = z.iso.date();
export type CalendarDate = z.infer<typeof CalendarDate>;

// ---------------------------------------------------------------------------
// Status
// ---------------------------------------------------------------------------

export const TASK_STATUSES = ['backlog', 'todo', 'in_progress', 'in_review', 'done', 'canceled'] as const;
export const TaskStatus = z.enum(TASK_STATUSES);
export type TaskStatus = z.infer<typeof TaskStatus>;

export const TASK_STATUS_LABELS: Record<TaskStatus, string> = {
  backlog: 'Backlog',
  todo: 'Todo',
  in_progress: 'In progress',
  in_review: 'In review',
  done: 'Done',
  canceled: 'Canceled',
};

/** Statuses that count as open work (project counts, rail badges). */
export const OPEN_TASK_STATUSES = ['backlog', 'todo', 'in_progress', 'in_review'] as const;
export const OpenTaskStatus = z.enum(OPEN_TASK_STATUSES);
export type OpenTaskStatus = z.infer<typeof OpenTaskStatus>;

export function isOpenStatus(status: TaskStatus): status is OpenTaskStatus {
  return (OPEN_TASK_STATUSES as readonly string[]).includes(status);
}

// ---------------------------------------------------------------------------
// Priority
// ---------------------------------------------------------------------------

/** Ordered from lowest to highest. The index is the smallint stored in the database. */
export const PRIORITIES = ['none', 'low', 'medium', 'high', 'urgent'] as const;
export const Priority = z.enum(PRIORITIES);
export type Priority = z.infer<typeof Priority>;

export const PRIORITY_LABELS: Record<Priority, string> = {
  none: 'No priority',
  low: 'Low',
  medium: 'Medium',
  high: 'High',
  urgent: 'Urgent',
};

/** Database value (0 to 4) for a priority. */
export function priorityToValue(priority: Priority): number {
  return PRIORITIES.indexOf(priority);
}

/** Priority for a database value; throws on anything outside 0 to 4. */
export function priorityFromValue(value: number): Priority {
  const priority = PRIORITIES[value];
  if (priority === undefined) throw new RangeError(`Invalid priority value: ${value}`);
  return priority;
}

// ---------------------------------------------------------------------------
// People and agents
// ---------------------------------------------------------------------------

export const UserKind = z.enum(['person', 'agent']);
export type UserKind = z.infer<typeof UserKind>;

/** Workspace roles from the Better Auth organization plugin. owner and admin count as admin. */
export const WorkspaceRole = z.enum(['owner', 'admin', 'member']);
export type WorkspaceRole = z.infer<typeof WorkspaceRole>;

export function isAdminRole(role: WorkspaceRole): boolean {
  return role === 'owner' || role === 'admin';
}

export const ApiKeyAccess = z.enum(['read', 'write']);
export type ApiKeyAccess = z.infer<typeof ApiKeyAccess>;

// ---------------------------------------------------------------------------
// Project keys
// ---------------------------------------------------------------------------

export const PROJECT_KEY_PATTERN = /^[A-Z][A-Z0-9]{1,5}$/;
const PROJECT_KEY_MESSAGE = 'Use 2 to 6 letters or digits, starting with a letter';

/** Canonical project key, e.g. PAY. Strict: no case folding. Use for outputs and stored values. */
export const ProjectKey = z.string().regex(PROJECT_KEY_PATTERN, PROJECT_KEY_MESSAGE);
export type ProjectKey = z.infer<typeof ProjectKey>;

/** Project key as typed by a person or agent: trimmed and upper-cased before validation. */
export const ProjectKeyInput = z
  .string()
  .trim()
  .toUpperCase()
  .regex(PROJECT_KEY_PATTERN, PROJECT_KEY_MESSAGE);

/**
 * Suggests a key from a project name, as in the New project dialog: the first three letters or
 * digits of the first word that starts with a letter ("Billing reconciliation" gives "BIL").
 * Short first words borrow from the next ones. Returns null when nothing valid can be built.
 */
export function suggestProjectKey(name: string): string | null {
  const words = name
    .normalize('NFKD')
    .replace(/[^A-Za-z0-9\s]/g, '')
    .toUpperCase()
    .split(/\s+/)
    .filter(Boolean);
  const first = words.findIndex((word) => /^[A-Z]/.test(word));
  if (first === -1) return null;
  const candidate = words.slice(first).join('').slice(0, 3);
  return PROJECT_KEY_PATTERN.test(candidate) ? candidate : null;
}

// ---------------------------------------------------------------------------
// Workspace slugs (0.10, PM-39)
// ---------------------------------------------------------------------------

/** Shortest and longest workspace slug. */
export const WORKSPACE_SLUG_MIN_LENGTH = 2;
export const WORKSPACE_SLUG_MAX_LENGTH = 40;

/**
 * Lowercase letters, digits and single hyphens, starting with a letter and not ending with a hyphen.
 * The database checks the same rule on workspace_slug_alias.
 */
export const WORKSPACE_SLUG_PATTERN = /^[a-z][a-z0-9]*(?:-[a-z0-9]+)*$/;

/**
 * Slugs no workspace may take: they are, or may become, top-level paths of the web app. Core
 * refuses them with SLUG_RESERVED.
 */
export const WORKSPACE_SLUG_RESERVED = [
  'api',
  'w',
  'new',
  'settings',
  'admin',
  'setup',
  'signin',
  'invite',
  'welcome',
  'help',
  'docs',
  'static',
  'assets',
] as const;
export type ReservedWorkspaceSlug = (typeof WORKSPACE_SLUG_RESERVED)[number];

export function isReservedWorkspaceSlug(slug: string): slug is ReservedWorkspaceSlug {
  return (WORKSPACE_SLUG_RESERVED as readonly string[]).includes(slug);
}

export const WORKSPACE_SLUG_MESSAGES = {
  length: `Use ${WORKSPACE_SLUG_MIN_LENGTH} to ${WORKSPACE_SLUG_MAX_LENGTH} characters.`,
  start: 'Start with a letter.',
  characters: 'Use lowercase letters, digits and hyphens.',
  hyphens: 'Use single hyphens between letters or digits, not at the end.',
  reserved: 'This address is reserved. Pick another.',
} as const;

/**
 * The format part of the slug rule, with one message per broken rule so a form can say what to fix.
 * Reserved words pass here; WorkspaceSlug refuses them too.
 */
const WorkspaceSlugFormat = z
  .string()
  .min(WORKSPACE_SLUG_MIN_LENGTH, WORKSPACE_SLUG_MESSAGES.length)
  .max(WORKSPACE_SLUG_MAX_LENGTH, WORKSPACE_SLUG_MESSAGES.length)
  .regex(/^[a-z]/, WORKSPACE_SLUG_MESSAGES.start)
  .regex(/^[a-z0-9-]*$/, WORKSPACE_SLUG_MESSAGES.characters)
  .regex(WORKSPACE_SLUG_PATTERN, WORKSPACE_SLUG_MESSAGES.hyphens);

/**
 * A workspace slug as stored and shown, e.g. `acme`: the format rule and not a reserved word.
 * Strict: no case folding or trimming.
 */
export const WorkspaceSlug = WorkspaceSlugFormat.refine((value) => !isReservedWorkspaceSlug(value), {
  message: WORKSPACE_SLUG_MESSAGES.reserved,
});
export type WorkspaceSlug = z.infer<typeof WorkspaceSlug>;

/**
 * A slug as typed in the New workspace dialog or General settings: trimmed and lower-cased, then
 * checked against the format rule. Reserved words pass, so core answers them with SLUG_RESERVED
 * (400) as it answers a slug in use with SLUG_TAKEN (409); `isReservedWorkspaceSlug` lets a form
 * say so before it submits.
 */
export const WorkspaceSlugInput = z.string().trim().toLowerCase().pipe(WorkspaceSlugFormat);

/** Suffix that makes a too-short or reserved suggestion a slug of its own: `admin-workspace`. */
const SLUG_FALLBACK_SUFFIX = '-workspace';

/**
 * Suggests a slug from a workspace name, as the New workspace dialog does while you type: accents
 * dropped, lower-cased, every run of other characters turned into one hyphen ("Acme Corp." gives
 * `acme-corp`). A name that starts with a digit gets `w-`; a result that is too short or reserved
 * gets `-workspace`. Always returns a valid WorkspaceSlug; core appends a number while it is taken
 * (workspaceSlugWithNumber).
 */
export function suggestWorkspaceSlug(name: string): string {
  let slug = name
    .normalize('NFKD')
    .replace(/[\u0300-\u036f]/g, '')
    .toLowerCase()
    .replace(/[^a-z0-9]+/g, '-')
    .replace(/^-+|-+$/g, '');
  if (slug === '') slug = 'workspace';
  else if (!/^[a-z]/.test(slug)) slug = `w-${slug}`;
  slug = trimSlug(slug, WORKSPACE_SLUG_MAX_LENGTH);
  if (slug.length < WORKSPACE_SLUG_MIN_LENGTH || isReservedWorkspaceSlug(slug)) {
    slug = `${trimSlug(slug, WORKSPACE_SLUG_MAX_LENGTH - SLUG_FALLBACK_SUFFIX.length)}${SLUG_FALLBACK_SUFFIX}`;
  }
  return slug;
}

/**
 * The nth candidate for a suggested slug: the slug itself for 1, else the slug cut short enough to
 * end in `-<n>` within the length limit (`acme-2`). Pass a valid slug and n >= 1.
 */
export function workspaceSlugWithNumber(slug: string, n: number): string {
  if (n <= 1) return slug;
  const suffix = `-${n}`;
  return `${trimSlug(slug, WORKSPACE_SLUG_MAX_LENGTH - suffix.length)}${suffix}`;
}

/**
 * Who may create a workspace, from the WORKSPACE_CREATION setting: any person (`everyone`, the
 * default), or only people who own a workspace already (`owners`). Agents never do. Core refuses the
 * others with WORKSPACE_CREATION_OFF.
 */
export const WORKSPACE_CREATION_POLICIES = ['everyone', 'owners'] as const;
export const WorkspaceCreationPolicy = z.enum(WORKSPACE_CREATION_POLICIES);
export type WorkspaceCreationPolicy = z.infer<typeof WorkspaceCreationPolicy>;
export const DEFAULT_WORKSPACE_CREATION = 'everyone' satisfies WorkspaceCreationPolicy;

/** Cuts a slug to `length` characters without leaving a trailing hyphen. */
function trimSlug(slug: string, length: number): string {
  return slug.slice(0, length).replace(/-+$/, '');
}

// ---------------------------------------------------------------------------
// Task keys
// ---------------------------------------------------------------------------

/** Largest task number: Postgres integer range. */
export const MAX_TASK_NUMBER = 2_147_483_647;

/**
 * A task key: project key, dash, number, and for Backlog.md subtasks one or more `.N` parts
 * (PAY-142, PAY-786.1, PAY-786.1.2). Suffix parts are 1 to 99999 without leading zeros.
 * Groups: 1 project key, 2 number, 3 suffix with its leading dot (or undefined).
 */
export const TASK_KEY_PATTERN = /^([A-Z][A-Z0-9]{1,5})-([1-9][0-9]{0,9})((?:\.[1-9][0-9]{0,4})+)?$/;
const TASK_KEY_MESSAGE = 'Use a task key like PAY-142 or PAY-786.1';

/** A key suffix without its leading dot: `1` or `1.2`. Stored in task.key_suffix. */
export const KEY_SUFFIX_PATTERN = /^[1-9][0-9]{0,4}(?:\.[1-9][0-9]{0,4})*$/;
export const KeySuffix = z.string().regex(KEY_SUFFIX_PATTERN, 'Use a suffix like 1 or 1.2');

export interface TaskKeyParts {
  projectKey: string;
  number: number;
  /** The subtask suffix without the leading dot (`1`, `1.2`); null for plain keys. */
  suffix: string | null;
}

/**
 * Splits a canonical (uppercase, trimmed) task key into project key, number and suffix. Returns
 * null when the value is not a task key or the number is out of range. TaskKeyParts and
 * parseTaskKey accept any case.
 */
export function splitTaskKey(value: string): TaskKeyParts | null {
  const match = TASK_KEY_PATTERN.exec(value);
  if (!match) return null;
  const number = Number(match[2]);
  if (!Number.isSafeInteger(number) || number > MAX_TASK_NUMBER) return null;
  return { projectKey: match[1] as string, number, suffix: match[3] ? match[3].slice(1) : null };
}

/** Canonical task key, e.g. PAY-142 or PAY-786.1. Strict: no case folding. Use for outputs. */
export const TaskKey = z
  .string()
  .regex(TASK_KEY_PATTERN, TASK_KEY_MESSAGE)
  .refine((value) => splitTaskKey(value) !== null, { message: 'Task number is out of range' });
export type TaskKey = z.infer<typeof TaskKey>;

/** Task key as typed: trimmed and upper-cased before validation, so `pay-142` is accepted. */
export const TaskKeyInput = z
  .string()
  .trim()
  .toUpperCase()
  .regex(TASK_KEY_PATTERN, TASK_KEY_MESSAGE)
  .refine((value) => splitTaskKey(value) !== null, { message: 'Task number is out of range' });

/** Parses a task key (any case, surrounding spaces allowed) into its parts. */
export const TaskKeyParts = TaskKeyInput.transform((value) => splitTaskKey(value) as TaskKeyParts);

/**
 * Parses `PAY-142` into `{ projectKey: 'PAY', number: 142, suffix: null }` and `PAY-786.1.2` into
 * `{ projectKey: 'PAY', number: 786, suffix: '1.2' }`. Throws a ZodError on invalid input.
 */
export function parseTaskKey(value: string): TaskKeyParts {
  return TaskKeyParts.parse(value);
}

/** Like parseTaskKey but returns null instead of throwing. */
export function safeParseTaskKey(value: string): TaskKeyParts | null {
  const result = TaskKeyParts.safeParse(value);
  return result.success ? result.data : null;
}

/** `PAY-142`, or `PAY-786.1` with suffix `1`. A null, undefined or empty suffix gives the plain key. */
export function formatTaskKey(projectKey: string, number: number, suffix?: string | null): string {
  return suffix ? `${projectKey}-${number}.${suffix}` : `${projectKey}-${number}`;
}

// ---------------------------------------------------------------------------
// Backlog.md ids
// ---------------------------------------------------------------------------

/**
 * A Backlog.md task id as written in its files: a prefix of letters (task_prefix, default `task`;
 * drafts use `draft`), a dash, the number and optional `.N` subtask parts. Any case; numbers may
 * be zero-padded (zero_padded_ids). Groups: 1 prefix, 2 number, 3 suffix with its leading dot.
 */
export const BACKLOG_ID_PATTERN = /^([A-Za-z]{1,20})-([0-9]{1,12})((?:\.[0-9]{1,8})*)$/;
const BACKLOG_ID_MESSAGE = 'Use a Backlog.md id like BACK-786 or back-786.1';

export interface BacklogIdParts {
  /** Uppercase prefix: BACK, TASK, DRAFT. */
  prefix: string;
  number: number;
  /** Subtask suffix without the leading dot and without zero padding (`1`, `1.2`); null for top-level ids. */
  suffix: string | null;
}

/** Drops zero padding from one numeric part; null when nothing is left above zero or it is too long. */
function unpad(part: string, maxDigits: number): string | null {
  const trimmed = part.replace(/^0+/, '');
  if (trimmed === '' || trimmed.length > maxDigits) return null;
  return trimmed;
}

/**
 * Splits a Backlog.md id in any case into its normalised parts: uppercase prefix, number and
 * suffix without zero padding (back-007.01 gives BACK, 7, '1'). Null when it is not a Backlog.md
 * id, a part is zero, or the number does not fit a task number.
 */
export function parseBacklogId(value: string): BacklogIdParts | null {
  const match = BACKLOG_ID_PATTERN.exec(value.trim());
  if (!match) return null;
  const number = unpad(match[2] as string, 10);
  if (number === null || Number(number) > MAX_TASK_NUMBER) return null;
  const parts = (match[3] as string).split('.').slice(1);
  const suffix: string[] = [];
  for (const part of parts) {
    const unpadded = unpad(part, 5);
    if (unpadded === null) return null;
    suffix.push(unpadded);
  }
  return {
    prefix: (match[1] as string).toUpperCase(),
    number: Number(number),
    suffix: suffix.length ? suffix.join('.') : null,
  };
}

/** The canonical form of a Backlog.md id: uppercase, no zero padding (BACK-786.1). */
export function formatBacklogId(parts: BacklogIdParts): string {
  return formatTaskKey(parts.prefix, parts.number, parts.suffix);
}

/**
 * A Backlog.md id in any case, normalised to the canonical form: `back-007.1` becomes `BACK-7.1`.
 * task.backlog_id stores this form, and lookups compare against it.
 */
export const BacklogId = z
  .string()
  .trim()
  .max(64)
  .refine((value) => parseBacklogId(value) !== null, { message: BACKLOG_ID_MESSAGE })
  .transform((value) => formatBacklogId(parseBacklogId(value) as BacklogIdParts));
export type BacklogId = z.output<typeof BacklogId>;

/**
 * Addresses one task: its app key (PAY-786.1) or, in a project mirrored from Backlog.md, its
 * Backlog.md id (BACK-786.1). Trimmed and upper-cased; Backlog.md ids also lose zero padding.
 * Core tries the app key first, then the Backlog.md id. Every task route and CLI argument takes it.
 */
export const TaskRefInput = z
  .string()
  .trim()
  .max(64)
  .transform((value) => {
    const upper = value.toUpperCase();
    if (splitTaskKey(upper)) return upper;
    const backlog = parseBacklogId(upper);
    return backlog ? formatBacklogId(backlog) : upper;
  })
  .refine((value) => splitTaskKey(value) !== null || parseBacklogId(value) !== null, {
    message: 'Use a task key like PAY-142, PAY-786.1, or a Backlog.md id like BACK-786',
  });
export type TaskRefInput = z.output<typeof TaskRefInput>;

// ---------------------------------------------------------------------------
// Milestones
// ---------------------------------------------------------------------------

/** Planned until a task in it starts, Active then, Completed only by hand. */
export const MILESTONE_STATUSES = ['planned', 'active', 'completed'] as const;
export const MilestoneStatus = z.enum(MILESTONE_STATUSES);
export type MilestoneStatus = z.infer<typeof MilestoneStatus>;

export const MILESTONE_STATUS_LABELS: Record<MilestoneStatus, string> = {
  planned: 'Planned',
  active: 'Active',
  completed: 'Completed',
};

// ---------------------------------------------------------------------------
// Cycles
// ---------------------------------------------------------------------------

/** Derived: Completed once ended, Current while today is within its dates, otherwise Upcoming. */
export const CYCLE_STATES = ['upcoming', 'current', 'completed'] as const;
export const CycleState = z.enum(CYCLE_STATES);
export type CycleState = z.infer<typeof CycleState>;

export const CYCLE_STATE_LABELS: Record<CycleState, string> = {
  upcoming: 'Upcoming',
  current: 'Current',
  completed: 'Completed',
};

/** Shortest and longest cycle in days, both ends included. */
export const MIN_CYCLE_DAYS = 1;
export const MAX_CYCLE_DAYS = 56;
/** Length of the first cycle of a project; later cycles default to the previous one's length. */
export const DEFAULT_CYCLE_DAYS = 14;

/** Largest cycle number: Postgres integer range. */
export const MAX_CYCLE_NUMBER = 2_147_483_647;

/** A cycle number. Query strings and path parameters carry it as text, so digits are accepted too. */
export const CycleNumber = z.union([
  z.number().int().min(1).max(MAX_CYCLE_NUMBER),
  z
    .string()
    .trim()
    .regex(/^[1-9][0-9]{0,9}$/, 'Use a cycle number like 12')
    .transform(Number)
    .pipe(z.number().max(MAX_CYCLE_NUMBER, 'Cycle number is out of range')),
]);
export type CycleNumber = z.output<typeof CycleNumber>;

export const CYCLE_CURRENT = 'current';
export const CYCLE_NEXT = 'next';

/**
 * Addresses a cycle of a project without its id: a number, the current cycle, or the next upcoming
 * one. Agents use it so they never need ids.
 */
export const CycleSelector = z.union([z.literal(CYCLE_CURRENT), z.literal(CYCLE_NEXT), CycleNumber], {
  error: 'Use a cycle number, current or next',
});
export type CycleSelector = z.output<typeof CycleSelector>;

/** Number of days from `start` to `end`, both included. Both are CalendarDate strings. */
export function cycleLengthDays(start: string, end: string): number {
  return Math.round((Date.parse(`${end}T00:00:00Z`) - Date.parse(`${start}T00:00:00Z`)) / 86_400_000) + 1;
}

