/** mirror keeps following the default branch; import reads once, then detaches. */
export const BACKLOG_MODES = ['mirror', 'import'] as const;
export const BacklogMode = z.enum(BACKLOG_MODES);
export type BacklogMode = z.infer<typeof BacklogMode>;

export const BACKLOG_MODE_LABELS: Record<BacklogMode, string> = {
  mirror: 'Mirror',
  import: 'Import',
};

/**
 * setup: created, first read not finished. healthy: every file read and every value mapped.
 * warnings: files skipped or values fell back. failed: the last refresh failed (last good state
 * kept). paused: the connection is missing, rejected or unreachable. detached: for good.
 */
export const BACKLOG_STATES = [
  'setup',
  'reading',
  'healthy',
  'warnings',
  'failed',
  'paused',
  'detached',
] as const;
export const BacklogState = z.enum(BACKLOG_STATES);
export type BacklogState = z.infer<typeof BacklogState>;

export const BACKLOG_STATE_LABELS: Record<BacklogState, string> = {
  setup: 'Setting up',
  reading: 'Refreshing',
  healthy: 'Mirroring',
  warnings: 'Mirroring, with problems',
  failed: 'Last refresh failed',
  paused: 'Paused',
  detached: 'Detached',
};

/** What started a refresh. cli is zamu backlog refresh (through the API); manual is Refresh now. */
export const BACKLOG_TRIGGERS = ['setup', 'webhook', 'manual', 'cli', 'poll'] as const;
export const BacklogTrigger = z.enum(BACKLOG_TRIGGERS);
export type BacklogTrigger = z.infer<typeof BacklogTrigger>;

export const BACKLOG_TRIGGER_LABELS: Record<BacklogTrigger, string> = {
  setup: 'setup',
  webhook: 'webhook',
  manual: 'Refresh now',
  cli: 'zamu backlog refresh',
  poll: 'hourly check',
};

/**
 * Who wrote an activity row: the app (a person, an agent or the system), a Backlog.md refresh, or
 * (M7) a git host event about a pull or merge request (origin git, originRef the request URL).
 */
export const ACTIVITY_ORIGINS = ['app', 'backlog', 'git'] as const;
export const ActivityOrigin = z.enum(ACTIVITY_ORIGINS);
export type ActivityOrigin = z.infer<typeof ActivityOrigin>;

/** Name shown for activity a Backlog.md refresh wrote (actor null, origin backlog). */
export const BACKLOG_ACTOR_NAME = 'Backlog.md';

/** M7: name shown for activity Zamu's own jobs wrote (actor null, origin app): the archive job, cycle ends. */
export const ZAMU_ACTOR_NAME = 'Zamu';

/** M7: name shown for activity a git host wrote (actor null, origin git), per provider. */
export const GIT_ACTOR_NAMES: Record<GitProvider, string> = {
  github: 'GitHub',
  gitlab: 'GitLab',
  gitea: 'Forgejo',
};

/**
 * Task fields Backlog.md owns while the project mirrors. Contract field names. M5 adds labels,
 * dueDate, blockedBy and parent (filled from the files on refresh). M6 adds the work record:
 * criteria, doneItems, plan and finalSummary (every item operation on them is refused).
 */
export const TASK_OWNED_FIELDS = [
  'title',
  'description',
  'status',
  'priority',
  'assignee',
  'milestone',
  'createdAt',
  'labels',
  'dueDate',
  'blockedBy',
  'parent',
  'criteria',
  'doneItems',
  'plan',
  'finalSummary',
] as const;
export const TaskOwnedField = z.enum(TASK_OWNED_FIELDS);
export type TaskOwnedField = z.infer<typeof TaskOwnedField>;

/** Milestone fields Backlog.md owns while the project mirrors (create and delete are refused too). */
export const MILESTONE_OWNED_FIELDS = ['name', 'description', 'targetDate', 'status'] as const;
export const MilestoneOwnedField = z.enum(MILESTONE_OWNED_FIELDS);
export type MilestoneOwnedField = z.infer<typeof MilestoneOwnedField>;

/**
 * Project fields the mirror constrains: the key (the project has tasks), the repository (clearing
 * it pauses the mirror; see M3 plan section 5) and turning milestones off.
 */
export const PROJECT_OWNED_FIELDS = ['key', 'repository', 'usesMilestones'] as const;
export const ProjectOwnedField = z.enum(PROJECT_OWNED_FIELDS);
export type ProjectOwnedField = z.infer<typeof ProjectOwnedField>;

// ---------------------------------------------------------------------------
// Labels (M5)
// ---------------------------------------------------------------------------

/** Longest label name in characters. Names are unique per project, ignoring case. */
export const MAX_LABEL_NAME_LENGTH = 40;

/** Number of palette hues. A label colour is 1 to LABEL_COLOR_COUNT, drawn with --label-N. */
export const LABEL_COLOR_COUNT = 9;
export const LabelColor = z
  .number()
  .int()
  .min(1, `Use a colour from 1 to ${LABEL_COLOR_COUNT}`)
  .max(LABEL_COLOR_COUNT, `Use a colour from 1 to ${LABEL_COLOR_COUNT}`);
export type LabelColor = z.infer<typeof LabelColor>;

/** app: created in the app. backlog: read from Backlog.md files; the name is locked, the colour isn't. */
export const LABEL_SOURCES = ['app', 'backlog'] as const;
export const LabelSource = z.enum(LABEL_SOURCES);
export type LabelSource = z.infer<typeof LabelSource>;

// ---------------------------------------------------------------------------
// Due dates (M5)
// ---------------------------------------------------------------------------

/**
 * "Due soon": an open task due today or within this many days after today, in APP_TIME_ZONE
 * (today, tomorrow, the day after). Overdue: an open task due before today.
 */
export const DUE_SOON_DAYS = 2;

/** How a due date reads, for chips and filters. done covers Done and Canceled tasks with a date. */
export const DUE_STATES = ['none', 'future', 'soon', 'today', 'overdue', 'done'] as const;
export const DueState = z.enum(DUE_STATES);
export type DueState = z.infer<typeof DueState>;

/**
 * The due state of a task. `today` is the CalendarDate of today in APP_TIME_ZONE; dates compare
 * as strings because CalendarDate is YYYY-MM-DD.
 */
export function dueState(dueDate: string | null, status: TaskStatus, today: string): DueState {
  if (dueDate === null) return 'none';
  if (!isOpenStatus(status)) return 'done';
  if (dueDate < today) return 'overdue';
  if (dueDate === today) return 'today';
  return cycleLengthDays(today, dueDate) - 1 <= DUE_SOON_DAYS ? 'soon' : 'future';
}

// ---------------------------------------------------------------------------
// Archive and check-again days (M7)
// ---------------------------------------------------------------------------

/** project.archiveAfterDays: Done and Canceled tasks are archived this many days after they closed. */
export const ARCHIVE_AFTER_DAYS_MIN = 1;
export const ARCHIVE_AFTER_DAYS_MAX = 365;
/** What new projects start with. Projects from before M7 start with archiving off (null). */
export const DEFAULT_ARCHIVE_AFTER_DAYS = 14;

export const ArchiveAfterDays = z
  .number()
  .int('Use a whole number of days')
  .min(ARCHIVE_AFTER_DAYS_MIN, `Use ${ARCHIVE_AFTER_DAYS_MIN} to ${ARCHIVE_AFTER_DAYS_MAX} days`)
  .max(ARCHIVE_AFTER_DAYS_MAX, `Use ${ARCHIVE_AFTER_DAYS_MIN} to ${ARCHIVE_AFTER_DAYS_MAX} days`);

/** Longest check-again reason, in characters after trimming. */
export const MAX_CHECK_AGAIN_REASON_LENGTH = 200;

/**
 * waiting: the check-again day is after today. ready: it is today or has passed. Today is the day in
 * APP_TIME_ZONE; days compare as strings because CalendarDate is YYYY-MM-DD.
 */
export const CHECK_AGAIN_STATES = ['waiting', 'ready'] as const;
export const CheckAgainState = z.enum(CHECK_AGAIN_STATES);
export type CheckAgainState = z.infer<typeof CheckAgainState>;

export function checkAgainState(on: string, today: string): CheckAgainState {
  return on > today ? 'waiting' : 'ready';
}

/** Longest work branch kept on a task, in characters. */
export const MAX_WORK_BRANCH_LENGTH = 255;

// ---------------------------------------------------------------------------
// Plan links, waves and gates (M8)
// ---------------------------------------------------------------------------

/** Longest milestone plan link, in characters after trimming. One line. */
export const MAX_PLAN_URL_LENGTH = 2_000;

/**
 * How a plan link shows: link (starts with http:// or https://, opens in a new tab) or path (a file
 * path, shown in monospace). Both can be copied.
 */
export const PLAN_URL_KINDS = ['link', 'path'] as const;
export const PlanUrlKind = z.enum(PLAN_URL_KINDS);
export type PlanUrlKind = z.infer<typeof PlanUrlKind>;

export function planUrlKind(value: string): PlanUrlKind {
  return /^https?:\/\//i.test(value.trim()) ? 'link' : 'path';
}

/** Longest wave name, in characters after trimming. Unique per milestone, ignoring case. */
export const MAX_WAVE_NAME_LENGTH = 100;
/** Longest gate description (Markdown), in characters. */
export const MAX_GATE_DESCRIPTION_LENGTH = 4_000;
/** Longest gate result note (Markdown), in characters. Every result needs one. */
export const MAX_GATE_NOTE_LENGTH = 10_000;
/** Most open task keys a wave lists in openKeys (and GATE_TASKS_OPEN in its problem). */
export const MAX_WAVE_OPEN_KEYS = 50;

/**
 * A gate's state is its latest recorded result: open until the first one, then passed or failed.
 * A result can be recorded again either way at any time; there is no way back to open.
 */
export const GATE_STATES = ['open', 'passed', 'failed'] as const;
export const GateState = z.enum(GATE_STATES);
export type GateState = z.infer<typeof GateState>;

export const GATE_STATE_LABELS: Record<GateState, string> = {
  open: 'Open',
  passed: 'Passed',
  failed: 'Failed',
};

/** What can be recorded on a gate. */
export const GATE_RESULT_STATES = ['passed', 'failed'] as const;
export const GateResultState = z.enum(GATE_RESULT_STATES);
export type GateResultState = z.infer<typeof GateResultState>;

/** A wave's number is its position in the milestone, from 1. Shown as W3. */
export function formatWaveNumber(number: number): string {
  return `W${number}`;
}

/** A wave as the CLI names it within a milestone: its number (3 or W3) or its name. */
export type WaveReference = { kind: 'number'; number: number } | { kind: 'name'; name: string };

/** Reads `3`, `W3` or `w3` as a number, anything else (trimmed) as a name. */
export function parseWaveReference(value: string): WaveReference {
  const trimmed = value.trim();
  const match = /^[Ww]?([1-9][0-9]{0,5})$/.exec(trimmed);
  return match ? { kind: 'number', number: Number(match[1]) } : { kind: 'name', name: trimmed };
}

// ---------------------------------------------------------------------------
// Theme
// ---------------------------------------------------------------------------

/** A person's theme choice. System follows prefers-color-scheme. */
export const THEMES = ['system', 'light', 'dark'] as const;
export const Theme = z.enum(THEMES);
export type Theme = z.infer<typeof Theme>;

export const THEME_LABELS: Record<Theme, string> = {
  system: 'System',
  light: 'Light',
  dark: 'Dark',
};
